#!/usr/bin/env bash
set -euo pipefail

SITE_ROOT="${STATV2_SITE_ROOT:-/var/www/statv2}"
SKIP_HEALTH="${STATV2_V261_SKIP_HEALTH:-0}"
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="/root/statv2_before_v26_1_${STAMP}.tar.gz"
TMP="$(mktemp -d /tmp/statv2-v261.XXXXXX)"
trap 'rm -rf "$TMP"' EXIT

GATE="$SITE_ROOT/gate.html"
INDEX="$SITE_ROOT/index_v2.html"
MULTI="$SITE_ROOT/multiobject.js"
SW="$SITE_ROOT/sw.js"
OFFLINE="$SITE_ROOT/offline_v261.js"

for f in "$GATE" "$INDEX" "$MULTI" "$SW"; do
  [ -f "$f" ] || { echo "ERROR: не найден $f" >&2; exit 1; }
done

sha(){ sha256sum "$1" | awk '{print $1}'; }

BASE_GATE="b573219479618de9603a47a9f75607ceb1814b68ac0c6cd04e89c0a38aee3c59"
BASE_INDEX="4f4bb5ec114d28c8e8d199d2fdf5549bdd12ad348949ceffca10c792fc18caf0"
BASE_MULTI="6955a647ba593190284b55af7884a293e03fb20ee5f633c382cf387265151c38"
BASE_SW="a09726efb072b95e7631bcbb62345198662e69d5556e7873790de63ad92dcbb2"
FINAL_GATE="eb2e2d8101f618b53f05eb8a99cc94694774e0096addb39b6ff45e94eac6c98e"
FINAL_INDEX="8a6388c1ef8569702457cdb8dbf5c58b92183a89c55c5d64e5c8b78961d263d1"
FINAL_MULTI="afca7e55ee79befe8397e934cd482d9d1a30ca8871911344eeef58a398412e4d"
FINAL_SW="1208d8cda0b3e0c4546cc15276b5d1613c3ea7556794dbf8e15e7ce624bc059e"
FINAL_OFFLINE="ddf71d1429cbc5514c9e7ec011e866a2e1313f3fd8d286227fbd495f9bb478a6"

if [ "$(sha "$GATE")" = "$FINAL_GATE" ] && \
   [ "$(sha "$INDEX")" = "$FINAL_INDEX" ] && \
   [ "$(sha "$MULTI")" = "$FINAL_MULTI" ] && \
   [ "$(sha "$SW")" = "$FINAL_SW" ] && \
   [ -f "$OFFLINE" ] && [ "$(sha "$OFFLINE")" = "$FINAL_OFFLINE" ]; then
  echo "STATV2 V26.1 уже установлен — изменений не требуется."
  exit 0
fi

echo "===== 1. VERIFY V26 BASE ====="
check_base(){
  local file="$1" expected="$2" name="$3" got
  got="$(sha "$file")"
  echo "$name: $got"
  if [ "$got" != "$expected" ]; then
    echo "ERROR: $name отличается от проверенной V26-базы." >&2
    echo "Ожидалось: $expected" >&2
    echo "Получено:  $got" >&2
    echo "Ничего не изменено." >&2
    exit 1
  fi
}
check_base "$GATE" "$BASE_GATE" "gate.html"
check_base "$INDEX" "$BASE_INDEX" "index_v2.html"
check_base "$MULTI" "$BASE_MULTI" "multiobject.js"
check_base "$SW" "$BASE_SW" "sw.js"

echo
echo "===== 2. BACKUP ====="
backup_files=("$GATE" "$INDEX" "$MULTI" "$SW")
[ -f "$OFFLINE" ] && backup_files+=("$OFFLINE")
tar -czf "$BACKUP" -- "${backup_files[@]}"
chmod 600 "$BACKUP"
echo "Backup: $BACKUP"

decode_asset(){
  local name="$1" expected="$2" out="$TMP/$1"
  base64 -d | gzip -dc > "$out"
  local got="$(sha "$out")"
  [ "$got" = "$expected" ] || { echo "ERROR: повреждён встроенный asset $name" >&2; exit 1; }
}

echo
echo "===== 3. BUILD V26.1 ASSETS ====="
